function visualizeRegex() {
            const pattern = document.getElementById('regex-input').value;
            const canvas = document.getElementById('canvas');
            if (!pattern) {
                canvas.innerHTML = '<span class="text-slate-400 italic font-medium uppercase tracking-widest text-xs">Awaiting cryptographic pattern...</span>';
                return;
            }
            try {
                // Heuristic Parsing for Visualization
                // This logic is designed to stay local within the Canvas buffer.
                canvas.innerHTML = '';
                // Add Initial Terminal Node
                addNode('START', 'terminal');
                if (pattern.includes('^')) addNode('^ (BOL)', 'anchor');
                // Advanced Tokenizer Logic (Simplified for UI representation)
                const parts = pattern.match(/(\[.*?\]|\(.*?\)|[a-zA-Z0-9]+|[\*\+\?])/g) || [pattern];
                parts.forEach(part => {
                    if (part.startsWith('(')) addNode(part, 'group');
                    else if (part.startsWith('[')) addNode(part, 'class');
                    else if (['*', '+', '?'].includes(part)) addNode(part, 'quantifier');
                    else addNode(part, 'literal');
                });
                if (pattern.includes('$')) addNode('$ (EOL)', 'anchor');
                // Add Final Accepting State
                addNode('END', 'terminal');
            } catch (e) {
                canvas.innerHTML = `<div class="bg-red-50 p-6 rounded-2xl border-2 border-red-200 text-red-600 font-mono text-sm shadow-xl">
                    <p class="font-black mb-2 uppercase tracking-widest">Syntax Compromised</p>
                    <p>${e.message}</p>
                </div>`;
            }
        }
        function addNode(text, type) {
            const canvas = document.getElementById('canvas');
            const div = document.createElement('div');
            let colorClass = "bg-white border-slate-300";
            if (type === 'group') colorClass = "node-group border-purple-500";
            if (type === 'quantifier') colorClass = "node-quantifier border-amber-500";
            if (type === 'anchor') colorClass = "node-anchor border-emerald-500";
            if (type === 'class') colorClass = "node-class border-blue-500";
            if (type === 'terminal') colorClass = "bg-slate-900 border-slate-900 text-white";
            div.className = `node ${colorClass} transition-all hover:scale-110 active:scale-95 cursor-default`;
            div.innerHTML = `<span class="text-[9px] uppercase font-black opacity-40 mb-1 tracking-tighter">${type}</span><span class="font-mono font-bold break-all">${text}</span>`;
            // Generate Connection Vector (Arrow)
            if (canvas.children.length > 0) {
                const arrow = document.createElement('span');
                arrow.className = "text-slate-300 font-black text-xl mx-1";
                arrow.innerText = " to ";
                canvas.appendChild(arrow);
            }
            canvas.appendChild(div);
        }
        function clearInput() {
            if (!confirm("Purge logic buffer?")) return;
            document.getElementById('regex-input').value = "";
            visualizeRegex();
        }
        // --- SCROLL LOGIC ---
        // Initialize with standard Email regex
        document.addEventListener('DOMContentLoaded', () => {
            document.getElementById('regex-input').value = "^[\\w-\\.]+@([\\w-]+\\.)+[\\w-]{2,4}$";
            visualizeRegex();
        });
